// Release links accept calendar releases YY.MM.N[-rc.K] and historical 0.x releases.
const isReleaseVersion = (version: string): boolean =>
  /^(?:[1-9]\d\.(?:0[1-9]|1[0-2])\.(?:0|[1-9]\d*)|0\.(?:0|[1-9]\d*)\.(?:0|[1-9]\d*))(?:-rc\.[1-9]\d*)?$/.test(version);

export const getReleaseTag = (version: string): string | undefined => {
  if (!isReleaseVersion(version)) return undefined;
  return version.startsWith("0.") ? `v${version}` : version;
};
import { describe, expect, it } from "vitest";
import { getReleaseTag } from "@/lib/release-version";

describe("release version links", () => {
  it.each([
    "26.09.0",
    "26.09.1",
    "26.09.10",
    "26.09.0-rc.1",
    "26.09.1-rc.2",
    "27.01.0",
    "0.31.0",
    "0.31.0-rc.2",
  ])("links release %s", (version) => expect(getReleaseTag(version)).toBe(version.startsWith("0.") ? `v${version}` : version));

  it.each([
    "dev",
    "manual-abcdef0",
    "v26.09.0",
    "26.09",
    "26.09-rc.1",
    "26.9.0",
    "26.00.0",
    "26.13.0",
    "26.09.01",
    "26.09.0-rc.0",
    "26.09.0-dev.abc1234",
    "26.09.0extra",
    "0.31.0oops",
  ])("does not link non-release %s", (version) => expect(getReleaseTag(version)).toBeUndefined());
});

